+};
+
+const SIZE_PATTERN = /^\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]*)\s*$/;
+
 /** Parse a size such as "1.5 kB" into bytes. See README.md for the units. */
 export function parseSize(text: string): number {
-  throw new Error("not implemented");
+  const match = SIZE_PATTERN.exec(text);
+  if (match === null) {
+    throw new RangeError(`invalid size: ${JSON.stringify(text)}`);
+  }
+
+  const [, digits, unit] = match;
+  const factor = unit === "" ? 1 : UNIT_BYTES[unit.toLowerCase()];
+  if (factor === undefined) {
+    throw new RangeError(`invalid size: unknown unit ${JSON.stringify(unit)} in ${JSON.stringify(text)}`);
+  }
+
+  return Math.round(Number(digits) * factor);
 }
